import jwt

def decode_json_web_token(token: str, key: str) -> dict:
    try:
        payload = jwt.decode(token, key, algorithms=["HS256"])
        # Additional security checks
        if 'exp' in payload and payload['exp'] < jwt.utils.now():
            return {}
        if 'iss' in payload and payload['iss'] != 'your_issuer':
            return {}
        if 'aud' in payload and payload['aud'] != 'your_audience':
            return {}
        return payload
    except jwt.PyJWTError:
        return {}
    except Exception:
        return {}
